import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE o(org INT, status TEXT, total INT);
INSERT INTO o VALUES (1,'paid',10),(1,NULL,20),(2,'paid',5),(2,'paid',NULL);
''')
for r in db.execute('''SELECT org, COUNT(*), COUNT(status), SUM(total)
FROM o GROUP BY org ORDER BY org'''):
    print(r)
